/**
 * Hekki Web Components Engine — Sandboxes and mounts dynamic widgets generated by the AI agent.
 */
export function mountDynamicWidget(payload) {
    const widgetsPanel = document.getElementById('widgets-panel');
    if (!widgetsPanel) return;

    // Remove no-widgets fallback message if present
    const fallbackMsg = document.getElementById('no-widgets-msg');
    if (fallbackMsg) {
        fallbackMsg.remove();
    }

    // Check if widget already exists, remove it to overwrite
    const existing = document.getElementById(`widget-${payload.widget_id}`);
    if (existing) {
        existing.remove();
    }

    // Create panel container
    const panel = document.createElement('div');
    panel.id = `widget-${payload.widget_id}`;
    panel.className = 'panel';

    // Panel Header (Title + Close Button)
    const header = document.createElement('div');
    header.className = 'panel-title';
    header.style.display = 'flex';
    header.style.justify = 'space-between';
    header.innerHTML = `
        <span>${payload.title || 'Telemetry Widget'}</span>
        <span class="close-btn" style="cursor: pointer; font-size: 0.8rem; font-weight: normal;">[X]</span>
    `;

    // Content container
    const content = document.createElement('div');
    content.className = 'panel-content';

    panel.appendChild(header);
    panel.appendChild(content);
    widgetsPanel.appendChild(panel);

    // Attach Shadow DOM for CSS isolation
    const shadow = content.attachShadow({ mode: 'open' });
    
    // Inject CSS & HTML
    shadow.innerHTML = `
        <style>
            :host { display: block; font-family: 'Courier New', Courier, monospace; color: #ffffff; }
            ${payload.css || ''}
        </style>
        ${payload.html || ''}
    `;

    // Hook Close Button event
    header.querySelector('.close-btn').addEventListener('click', () => {
        panel.remove();
        restoreFallbackIfEmpty();
    });

    // Run custom widget JavaScript safely inside shadow context
    if (payload.js) {
        try {
            const runner = new Function('shadow', payload.js);
            runner(shadow);
        } catch (err) {
            console.error(`Dynamic widget [${payload.widget_id}] execution failed:`, err);
        }
    }
}

function restoreFallbackIfEmpty() {
    const widgetsPanel = document.getElementById('widgets-panel');
    if (widgetsPanel && widgetsPanel.children.length === 0) {
        const fallback = document.createElement('div');
        fallback.id = 'no-widgets-msg';
        fallback.className = 'panel';
        fallback.innerHTML = `
            <div class="panel-title">Active Widgets</div>
            <div style="color: var(--fg-muted); font-size: 0.9rem;">No active telemetry widgets. AI will mount here dynamically.</div>
        `;
        widgetsPanel.appendChild(fallback);
    }
}
